export function validateAuthoredLayeredPixels(base,levels){validateLayeredTexturePixels(base);const volume=base.dimension==='volumetexture',count=Math.floor(Math.log2(Math.max(base.width,base.height,volume?base.depth:1)));if(!Array.isArray(levels)||levels.length!==count)throw Error('레이어 밉을 마지막 1 크기까지 지정하세요.');let{width,height,depth}=base;for(const level of levels){width=Math.max(1,Math.floor(width/2));height=Math.max(1,Math.floor(height/2));if(volume)depth=Math.max(1,Math.floor(depth/2));validateLayeredTexturePixels(level);if(level.dimension!==base.dimension||level.width!==width||level.height!==height||level.depth!==depth)throw Error('레이어 밉 크기·슬라이스가 달라요.');}return levels;}
const linear=v=>{v/=255;return v<=.04045?v/12.92:((v+.055)/1.055)**2.4;};
function volumeDownsample(source,srgb){const width=Math.max(1,Math.floor(source.width/2)),height=Math.max(1,Math.floor(source.height/2)),depth=Math.max(1,Math.floor(source.depth/2)),data=new Float32Array(width*height*depth*4),raw=bytes(source.data);for(let z=0;z<depth;z++)for(let y=0;y<height;y++)for(let x=0;x<width;x++){
 const x0=x*source.width/width,x1=(x+1)*source.width/width,y0=y*source.height/height,y1=(y+1)*source.height/height,z0=z*source.depth/depth,z1=(z+1)*source.depth/depth,area=(x1-x0)*(y1-y0)*(z1-z0),at=(x+y*width+z*width*height)*4;
 for(let sz=Math.floor(z0);sz<Math.ceil(z1);sz++)for(let sy=Math.floor(y0);sy<Math.ceil(y1);sy++)for(let sx=Math.floor(x0);sx<Math.ceil(x1);sx++){const weight=(Math.min(sx+1,x1)-Math.max(sx,x0))*(Math.min(sy+1,y1)-Math.max(sy,y0))*(Math.min(sz+1,z1)-Math.max(sz,z0))/area,from=(sx+sy*source.width+sz*source.width*source.height)*4;for(let c=0;c<4;c++)data[at+c]+=(raw?(srgb&&c<3?linear(source.data[from+c]):source.data[from+c]/255):source.data[from+c])*weight;}
 }return{width,height,depth,data};}
function cookVolume(pixels,p,options,srgb){let{data}=pixels;if(p.flipGreen){data=new Uint8Array(data);for(let i=1;i<data.length;i+=4)data[i]=255-data[i];}let covered=0,sum=0;for(let i=3;i<data.length;i+=4){if(data[i]/255>=p.alphaCutoff)covered++;sum+=data[i]/255;}const target=covered/(data.length/4),levels=[],coverage=[],authored=options.authoredLevels;let raw={...pixels,data},mip=0,top=null;
 while(true){const last=raw.width===1&&raw.height===1&&raw.depth===1,selected=mip>=p.topMip&&(!p.maxSize||Math.max(raw.width,raw.height,raw.depth)<=p.maxSize)||last;if(selected){top??=mip;let level;if(mip===0)level={width:raw.width,height:raw.height,depth:raw.depth,data:raw.data,coverage:{scale:1,target,achieved:target,error:0,meanSourceAlpha:sum/(data.length/4),quantizationStep:1/(data.length/4)}};else{if(bytes(raw.data)){const values=new Float32Array(raw.data.length);for(let i=0;i<values.length;i++)values[i]=srgb&&i%4!==3?linear(raw.data[i]):raw.data[i]/255;raw={...raw,data:values};}level=uploadTextureMipLevel(raw,p,srgb,target);}levels.push({width:level.width,height:level.height,depth:level.depth,data:level.data});coverage.push({sourceMip:mip,...level.coverage});if(!p.mipmaps)break;}
  if(last)break;if(authored){const next=authored[mip];if(!next)throw Error('볼륨 밉이 빠졌어요.');let nextData=next.data;if(p.flipGreen){nextData=new Uint8Array(nextData);for(let i=1;i<nextData.length;i+=4)nextData[i]=255-nextData[i];}raw={...next,data:nextData};}else raw=volumeDownsample(raw,srgb);mip++;
 }return{levels,coverage,topMip:top};}
function cookLayers(pixels,p,options){const levels=[],coverage=[],slice=pixels.width*pixels.height*4;let topMip=0;for(let z=0;z<pixels.depth;z++){const view={width:pixels.width,height:pixels.height,data:pixels.data.subarray(z*slice,(z+1)*slice)},authoredLevels=options.authoredLevels?.map(l=>({width:l.width,height:l.height,data:l.data.subarray(z*l.width*l.height*4,(z+1)*l.width*l.height*4)})),cooked=cookTextureMips(view,p,{...(authoredLevels?{authoredLevels}:{})});topMip=cooked.report.topMip;for(let i=0;i<cooked.levels.length;i++){const l=cooked.levels[i],at=cooked.report.coverage[i];if(!levels[i]){const alias=i===0&&l.data===view.data;levels[i]={width:l.width,height:l.height,depth:pixels.depth,data:alias?pixels.data:new Uint8Array(l.width*l.height*pixels.depth*4)};coverage[i]={sourceMip:at.sourceMip,target:0,achieved:0,error:0,maxLayerError:0,meanSourceAlpha:0,quantizationStep:1/(l.width*l.height*pixels.depth)};}if(levels[i].data!==pixels.data)levels[i].data.set(l.data,z*l.width*l.height*4);const row=coverage[i];row.target+=at.target/pixels.depth;row.achieved+=at.achieved/pixels.depth;row.meanSourceAlpha+=at.meanSourceAlpha/pixels.depth;row.maxLayerError=Math.max(row.maxLayerError,at.error);row.error=Math.abs(row.achieved-row.target);}}return{levels,coverage,topMip};}
export function cookLayeredTextureMips(pixels,value={},options={}){validateLayeredTexturePixels(pixels);const p=textureImportPolicy(value),srgb=textureImportColorSpace(p)==='srgb';if(options.composite?.normalTexture)throw Error('노멀·거칠기 합성은 2D 텍스처에서 지정하세요.');if(options.authoredLevels!==undefined)validateAuthoredLayeredPixels(pixels,options.authoredLevels);const cooked=pixels.dimension==='volumetexture'?cookVolume(pixels,p,options,srgb):cookLayers(pixels,p,options);return{levels:cooked.levels,report:{policy:p,dimension:pixels.dimension,authored:options.authoredLevels!==undefined,colorSpace:srgb?'srgb':'linear',source:{width:pixels.width,height:pixels.height,depth:pixels.depth,bytes:pixels.data.byteLength,mipLevels:(options.authoredLevels?.length||0)+1},topMip:cooked.topMip,dimensions:cooked.levels.map(l=>[l.width,l.height,l.depth]),storedBytes:cooked.levels.reduce((sum,l)=>sum+l.data.byteLength,0),coverage:cooked.coverage,coverageScope:pixels.dimension==='volumetexture'?'whole volume':'per face/layer, aggregate and maximum residual reported',sourcePreserved:true}};}
export const layeredTextureImportContract=Object.freeze({dimensions:['texturearray','cubemap','volumetexture'],policy:'Optional import uses common role/color/normal/coverage/topMip/maxSize/mipmaps; old assets without import retain legacy loading. New texture assets start with explicit import defaults.',mips:'Array/cube depth constant; volume area-weighted 3D reductions floor-half XYZ. Authored levels validate fully and are never regenerated. Single-level policy supported.',coverage:'Each array/cube layer keeps its own silhouette; volume uses whole-volume coverage. Normal green flip and lower-level renormalization use common policy.',ownership:'RGBA8 slice-major; input preserved, base may alias CPU input; loader-owned source may transfer to one existing lazy mip worker; no second worker/per-frame cook.',limits:['Current image-decoded RGBA8; HDR/raw/GPU compression and RDO remain separate','Cubemap face filters are independent, no seamless cross-face footprint','Large source decode and CPU arrays still consume their actual memory; not whole GPU/RAM budgeting']});
